<script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>

<div id="react"></div>

<script type="text/babel">
  const MyCustomComponent = ({ triggerQuery, model, modelUpdate }) => {

    const [displayedImages, setDisplayedImages] = React.useState(300)
    const [hideTosChecked, setHideTosChecked] = React.useState(false);

    const [startDate, setStartDate] = React.useState('2024-10-10');
    const [endDate, setEndDate] = React.useState(() => {
  const d = new Date();
  d.setDate(d.getDate() + 1);
  return d.toISOString().split('T')[0];
});



    const handleLoadMore = () => {
      setDisplayedImages(displayedImages + 300)
      }

    const [checkedValues, setCheckedValues] = React.useState([1,2,4,8,16,32]);

  const handleCheckboxChange = (event) => {
    const value = event.target.value;
    if (event.target.checked) {
      setCheckedValues([...checkedValues, Number(value)]);
    } else {
      setCheckedValues(checkedValues.filter((item) => item !== +value));
    }
  }

    const filterImages = () => {
      let filteredImages = [...model.images];

      filteredImages = filterPos(filteredImages);
      filteredImages = filterNeg(filteredImages);
      filteredImages = filterNsfw(filteredImages);
      filteredImages = filterDate(filteredImages) 

      modelUpdate({ filteredImages });
};

      const filterPos = (images) => {
          const search = model.search.toLowerCase();
          return search ? images.filter(i => i.Prompt && i.Prompt.toLowerCase().includes(search)) : images;
      };

      const filterNeg = (images) => {
          const negSearch = model.negSearch.toLowerCase();
          return negSearch ? images.filter(i => i.negativePrompt && i.negativePrompt.toLowerCase().includes(negSearch)) : images;
      };

      const filterNsfw = (images => {
          return images.filter(i => checkedValues.includes(i.nsfwLevel))
      })

      const filterDate = (images => {
          const start = new Date(startDate).toISOString()
          const end = new Date(endDate).toISOString()

          return images.filter(i => i.createdAt >= start && i.createdAt <= end);
      })

    const showNoPromptOnly = () => {

      modelUpdate({ filteredImages: model.images.filter(i=> i.Prompt === null)})
}

    const showBlockedOnly = () => {

      modelUpdate({ filteredImages: model.images.filter(i=> i.ingestion === 'Blocked' && i.blockedFor !== 'AiNotVerified')})
}

    const clearFilter = () => {
        modelUpdate({ filteredImages: model.images })

        setHideTosChecked(false)
}

    const toggleImageSelection = (imageId) => {
      if(model.isDisabled){
        return
      }

      const isSelected = model.selectedImages.includes(imageId);

      const newSelectedImages = [...model.selectedImages];

      if (isSelected) {
        const indexToRemove = newSelectedImages.indexOf(imageId);
        if (indexToRemove !== -1) {
          newSelectedImages.splice(indexToRemove, 1);
        }
      } else {
        newSelectedImages.push(imageId);
      }

      modelUpdate({ selectedImages: newSelectedImages });
    }

    const handleModalOpen = () => triggerQuery(model.OpenModal);

    const resetDates = () => {
      setStartDate('2024-10-10');

      const d = new Date();
      d.setDate(d.getDate() + 1);
      const end = d.toISOString().split('T')[0];

      setEndDate(end);

      filterImages(); // ideally should use the updated dates or live in a useEffect
};

    function Box(){
      return (
        <h1>Hello</h1>
        //this was a test to see if components worked, it did
      )
    }

    return(
    <div className="card">
      <div className="content">
        <div className="filters">
          <div>
            <button onClick={() => filterImages()}>Filter</button>
          </div>
          <div>
            <button onClick={() => showBlockedOnly()}>Show only ToS'd</button>
          </div>
          <div>
            <button onClick={() => clearFilter()}>Clear Filter</button>
          </div>
         <div>
            <button onClick={() => showNoPromptOnly()}>No Prompt Only</button>
          </div>
          <div className="nsfwLevels">
            <div>
              <label for="1">PG</label>
              <input type="checkbox" name="1" value="1" onChange={handleCheckboxChange} checked={checkedValues.includes(1)}/>
            </div>
            <div>
              <label for="2">PG-13</label>
              <input type="checkbox" name="2" value="2" onChange={handleCheckboxChange} checked={checkedValues.includes(2)}/>
            </div>
            <div>
              <label for="4">R</label>
              <input type="checkbox" name="4" value="4" onChange={handleCheckboxChange}checked={checkedValues.includes(4)}/>
            </div>
            <div>
              <label for="8">X</label>
              <input type="checkbox" name="8" value="8" onChange={handleCheckboxChange}checked={checkedValues.includes(8)}/>
            </div>
            <div>
              <label for="16">XXX</label>
              <input type="checkbox" name="16" value="16" onChange={handleCheckboxChange}checked={checkedValues.includes(16)}/>
            </div>
            <div>
              <label for="32">ToS</label>
              <input type="checkbox" name="32" value="32" onChange={handleCheckboxChange}checked={checkedValues.includes(32)}/>
            </div>

              <div>
                <label htmlFor="startDate">Start Date:</label>
                <input
                  type="date"
                  id="startDate"
                  name="startDate"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
              </div>
              <div>
                <label htmlFor="endDate">End Date:</label>
                <input
                  type="date"
                  id="endDate"
                  name="endDate"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                />
              </div>
              <div>
                <button onClick={resetDates}>Reset Dates</button>
              </div>
          </div>
        </div>
        <div>
          {endDate}
        </div>
        <div className="image-grid">
        {model.filteredImages.slice(0, displayedImages).map((image, index) => (
          <div className="grid-cell" key={image.id}>
            <div className="image-cell">
               <div className="image-container">
        {image.Source.endsWith('.mp4') ? (
          <video
            width="300"
            controls
            onClick={() => toggleImageSelection(image.id)}
            preload="none"
          >
            <source src={image.Source} type="video/mp4" />
            Your browser does not support the video tag.
          </video>
        ) : (
          <img
            src={image.Source}
            width="300px"
            alt={'Maybe video, click me'}
            onClick={() => toggleImageSelection(image.id)}
            loading="lazy"
            title={
                image.Prompt
                ? 'POSITIVE PROMPT\n-----------------\n' + image.Prompt + (image.negativePrompt ? '\n\n\nNEGATIVE PROMPT\n-----------------\n' + image.negativePrompt : '')
                : "No prompt data available"
            }
          />
        )}
        <input
          type="checkbox"
          className="image-checkbox"
          checked={model.selectedImages.includes(image.id)}
          onClick={() => toggleImageSelection(image.id)}
        />
        <button
          className="image-link-button"
          onClick={(e) => {
            e.preventDefault();
            window.open(image.Link, '_blank');
          }}
        >
          Civit
        </button>
          {image.needsReview && (
          <div className="review-box">
            {image.needsReview}
          </div>
        )} 
          {image.ingestion === 'Blocked' && (
          <div className="ingestion-box">
            	<p>&#9851;</p>
          </div>
         )} 
          {image.blockedFor === 'AiNotVerified' && (
          <div className="ingestion-box">
            	<p>NoMetadata</p>
          </div>
         )} 
          {image.bounty && (
          <div className="bounty-box">
                Bounty
          </div>
         )} 
          {image.profile && (
          <div className="profile-box">
                Profile
          </div>
         )}
         {image.createdAt && (
          <div className="created-at-box">
            {image.createdAt.substring(0,10)}
          </div>
         )}

                 {/*  {image.blockedFor && (
          <div className="blocked-box">
            {image.blockedFor}
          </div>
        )}  */}  

  </div>
  </div>
          </div>
        ))}
  </div>
        <div>
          <button className="load-button" onClick={() => handleLoadMore()}>
            Load More
          </button>
        </div>
      </div>

    </div>
  )}

  // This is the entrypoint for the React component.
  const ConnectedComponent = Retool.connectReactComponent(MyCustomComponent)
  const container = document.getElementById('react')
  const root = ReactDOM.createRoot(container)
  root.render(<ConnectedComponent />)
</script>
